class OrderLine:
    price: float  # doit être > 0
    order_id: int  # doit référencer une commande existante

# 2. Repository -> 3. Service -> 4. API -> 5. Écran
def add_line(order_id, price):
    assert price > 0, "prix invalide"
    return repository.insert(order_id, price)

